import subprocess

def run(args, timeout=4):
    try:
        r=subprocess.run(["./executable"]+args, capture_output=True, text=True, timeout=timeout)
        return f"exit={r.returncode} outlen={len(r.stdout)} errlen={len(r.stderr)} out={repr(r.stdout[:2000])} err={repr(r.stderr[:500])}"
    except subprocess.TimeoutExpired as e:
        # try to get partial?
        return "TIMEOUT"

# test exit-after-time short with pipe (no tty, so ansible/download panic, others ok)
