{"command": "cat > src/main.rs <<'RS'
mod io;
mod duration;
mod app;
mod modules;

use clap::{Command, Arg, ArgAction};

fn build_cmd() -> Command {
    Command::new("genact")
        .about("A nonsense activity generator")
        .version("1.5.1")
        .author("Sven-Hendrik Haase <svenstaro@gmail.com>")
        .arg(
            Arg::new("list-modules")
                .short('l')
                .long("list-modules")
                .help("List available modules")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("modules")
                .short('m')
                .long("modules")
                .value_name("MODULES")
                .help("Run only these modules")
                .value_parser([
                    "ansible",
                    "bootlog",
                    "botnet",
                    "bruteforce",
                    "cargo",
                    "cc",
                    "composer",
                    "cryptomining",
                    "docker_build",
                    "docker_image_rm",
                    "download",
                    "julia",
                    "kernel_compile",
                    "memdump",
                    "mkinitcpio",
                    "rkhunter",
                    "simcity",
                    "terraform",
                    "uv",
                    "weblog",
                    "wpt",
                ])
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("speed-factor")
                .short('s')
                .long("speed-factor")
                .value_name("SPEED_FACTOR")
                .help("Global speed factor")
                .default_value("1")
                .value_parser(parse_speed),
        )
        .arg(
            Arg::new("instant-print-lines")
                .short('i')
                .long("instant-print-lines")
                .value_name("INSTANT_PRINT_LINES")
                .help("Instantly print this many lines")
                .default_value("0")
                .value_parser(clap::value_parser!(u32)),
        )
        .arg(
            Arg::new("inhibit")
                .long("inhibit")
                .help("Keep the computer awake and the display on while genact is running")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("exit-after-time")
                .long("exit-after-time")
                .value_name("EXIT_AFTER_TIME")
                .help("Exit after running for this long (format example: 2h10min)")
                .value_parser(parse_duration_arg),
        )
        .arg(
            Arg::new("exit-after-modules")
                .long("exit-after-modules")
                .value_name("EXIT_AFTER_MODULES")
                .help("Exit after running this many modules")
                .value_parser(parse_modules_count),
        )
        .arg(
            Arg::new("print-completions")
                .long("print-completions")
                .value_name("shell")
                .help("Generate completion file for a shell")
                .value_parser(["bash", "elvish", "fish", "powershell", "zsh"]),
        )
        .arg(
            Arg::new("print-manpage")
                .long("print-manpage")
                .help("Generate man page")
                .action(ArgAction::SetTrue),
        )
}

fn parse_speed(s: &str) -> Result<f64, String> {
    let v: f64 = s.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
    if v < 0.01 {
        return Err("Speed factor must be larger than 0.01".to_string());
    }
    Ok(v)
}

fn parse_modules_count(s: &str) -> Result<u32, String> {
    let v: u32 = s.parse().map_err(|e: std::num::ParseIntError| e.to_string())?;
    if v == 0 {
        return Err("Must be larger than 0".to_string());
    }
    Ok(v)
}

fn parse_duration_arg(s: &str) -> Result<std::time::Duration, String> {
    duration::parse_duration(s)
}

fn main() {
    let matches = build_cmd().try_get_matches().unwrap_or_else(|e| e.exit());

    if let Some(shell) = matches.get_one::<String>("print-completions") {
        let mut cmd = build_cmd();
        let shell_enum = match shell.as_str() {
            "bash" => clap_complete::shells::Bash,
            "elvish" => clap_complete::shells::Elvish,
            "fish" => clap_complete::shells::Fish,
            "powershell" => clap_complete::shells::PowerShell,
            "zsh" => clap_complete::shells::Zsh,
            _ => unreachable!(),
        };
        clap_complete::generate(shell_enum, &mut cmd, "genact", &mut std::io::stdout());
        return;
    }

    if matches.get_flag("print-manpage") {
        let cmd = build_cmd();
        let man = clap_mangen::Man::new(cmd);
        man.render(&mut std::io::stdout()).unwrap();
        return;
    }

    if matches.get_flag("list-modules") {
        println!("Available modules:");
        for m in [
            "ansible",
            "bootlog",
            "botnet",
            "bruteforce",
            "cargo",
            "cc",
            "composer",
            "cryptomining",
            "docker_build",
            "docker_image_rm",
            "download",
            "julia",
            "kernel_compile",
            "memdump",
            "mkinitcpio",
            "rkhunter",
            "simcity",
            "terraform",
            "uv",
            "weblog",
            "wpt",
        ] {
            println!("  {}", m);
        }
        return;
    }

    let speed: f64 = matches.get_one::<f64>("speed-factor").copied().unwrap_or(1.0);
    let instant: u32 = matches.get_one::<u32>("instant-print-lines").copied().unwrap_or(0);
    let exit_after_time: Option<std::time::Duration> =
        matches.get_one::<std::time::Duration>("exit-after-time").copied();
    let exit_after_modules: Option<u32> =
        matches.get_one::<u32>("exit-after-modules").copied();
    let selected: Vec<String> = matches
        .get_many::<String>("modules")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    app::run(selected, speed, instant, exit_after_time, exit_after_modules);
}
