// ansible
fn run_ansible(ctx: &mut Context) -> bool {
    let width = crate::io::terminal_width();
    let mut rng = rand::thread_rng();
    let w1 = rand_latin(&mut rng);
    let w2 = rand_latin(&mut rng);
    let setup_name = format!("{}_{}", w1, w2);
    let play_prefix = format!("PLAY [setup {}] ", setup_name);
    let stars = if width > play_prefix.len() { width - play_prefix.len() } else { 0 };
    let play_line = format!("{}{}", play_prefix, "*".repeat(stars));
    // print PLAY
    if ctx.should_exit() { return false; }
    {
        use std::io::Write;
        let mut out = std::io::stdout().lock();
        let _ = out.write_all(play_line.as_bytes());
        let _ = out.write_all(b"\r\n");
        let _ = out.write_all(b"\r\n");
        let _ = out.flush();
    }
    ctx.sleep(150);
    if ctx.should_exit() { return false; }
    let task_prefix = "TASK [Gathering Facts] ";
    let tstars = if width > task_prefix.len() { width - task_prefix.len() } else { 0 };
    let task_line = format!("{}{}", task_prefix, "*".repeat(tstars));
    {
        use std::io::Write;
        let mut out = std::io::stdout().lock();
        let _ = out.write_all(task_line.as_bytes());
        let _ = out.flush();
    }
    // number of hosts: random 5-12?
    let n = rng.gen_range(5..12);
    for _ in 0..n {
        if ctx.should_exit() { return false; }
        let host = if rng.gen_bool(0.5) {
            format!("{}.{}.{}.{}", rng.gen_range(1..255), rng.gen_range(0..255), rng.gen_range(0..255), rng.gen_range(1..255))
        } else {
            // ipv6
            format!("{:x}:{:x}:{:x}:{:x}:{:x}:{:x}:{:x}:{:x}", rng.gen_range(0..65535), rng.gen_range(0..65535), rng.gen_range(0..65535), rng.gen_range(0..65535), rng.gen_range(0..65535), rng.gen_range(0..65535), rng.gen_range(0..65535), rng.gen_range(0..65535))
        };
        let line = format!("\x1b[32mok: [{}]\x1b[0m", host);
        {
            use std::io::Write;
            let mut out = std::io::stdout().lock();
            let _ = out.write_all(line.as_bytes());
            let _ = out.write_all(b"\r\n");
            let _ = out.flush();
        }
        // handle instant
        if ctx.instant_left > 0 {
            ctx.instant_left -= 1;
        } else {
            ctx.sleep(180);
        }
        if ctx.should_exit() { return false; }
    }
    // need to account for PLAY/instant? PLAY and TASK also count as lines for instant? Original instant counts lines. Our sleep handling for PLAY/TASK used ctx.sleep which already handles instant. But we manually decremented for hosts. For PLAY/TASK we used sleep which handles instant. Good. But hosts we manually handled instant + sleep. Actually we did instant check manually, but also need to not double? We did: if instant_left>0 decrement else sleep. That's same as ctx.sleep but without the initial check? Good.
    // For simplicity, return true (completed). But ansible in original continues? Actually ansible module after hosts finishes? It just ends (no more output). So return true.
    true
}

