            let _ = out.flush();
        }
        // handle instant/speed: botnet progress is very fast, almost no sleep
        if ctx.instant_left > 0 {
            ctx.instant_left -= 1;
        } else {
            // tiny sleep scaled
            let adj = (2.0 / ctx.speed) as u64;
            if adj == 0 {
                // no sleep, but yield a bit
            } else {
                std::thread::sleep(std::time::Duration::from_millis(adj));
            }
        }
        // check exit every 50 iterations to be responsive? Already checked each.
    }
    // newline after progress
    {
        use std::io::Write;
        let mut out = std::io::stdout().lock();
        let _ = out.write_all(b"\r\n");
        let _ = out.flush();
