        // Address (16 hex) + two spaces + 8 bytes + two spaces + 8 bytes + two spaces + |ascii|
        let h1: String = bytes[0..8].iter().map(|b| format!("{:02x}", b)).collect::<Vec<_>>().join(" ");
        let h2: String = bytes[8..16].iter().map(|b| format!("{:02x}", b)).collect::<Vec<_>>().join(" ");
        let ascii: String = bytes.iter().map(|&b| if b.is_ascii_graphic() || b == b' ' { b as char } else { '.' }).collect();
