fn run_mkinitcpio(ctx: &mut Context) -> bool {
    if ctx.should_exit() { return false; }
    let mut rng = rand::thread_rng();
    let versions = ["3.17.3-1-MANJARO","2.6.32-431.el6.i686","5.15.0-1-generic","6.1.0-arch1-1"];
    let hooks = ["base","udev","autodetect","modconf","block","filesystems","keyboard","fsck","encrypt","lvm2","resume"];
    // mkinitcpio has fixed structure: Building image from preset default, then -k..., then Starting build, then hooks, then fallback, etc.
    // We'll loop 2 presets
    for _ in 0..3 {
        if !ctx.print("\x1b[1;32m==> \x1b[0m\x1b[1mBuilding image from preset: /etc/mkinitcpio.d/linux.preset: 'default'\x1b[0m", 250) { return false; }
        if !ctx.print("\x1b[1;34m  -> \x1b[0m\x1b[1m-k /boot/vmlinuz-linux -c /etc/mkinitcpio.conf -g /boot/initramfs-linux.img\x1b[0m", 200) { return false; }
        let ver = versions.choose(&mut rng).unwrap();
        if !ctx.print(&format!("\x1b[1;32m==> \x1b[0m\x1b[1mStarting build: {}\x1b[0m", ver), 200) { return false; }
        for _ in 0..4 {
            let h = hooks.choose(&mut rng).unwrap();
            if !ctx.print(&format!("\x1b[1;34m  -> \x1b[0m\x1b[1mRunning build hook: [{}]\x1b[0m", h), 180) { return false; }
        }
