        if !ctx.print("\x1b[1;34m  -> \x1b[0m\x1b[1m-k /boot/vmlinuz-linux -c /etc/mkinitcpio.conf -g /boot/initramfs-linux-fallback.img\x1b[0m", 200) { return false; }
