fn run_wpt(ctx: &mut Context) -> bool {
    let mut rng = rand::thread_rng();
    let total: u32 = rng.gen_range(20000..28000);
    if !ctx.print(&format!("Running {} tests in web-platform-tests", total), 200) { return false; }
    // wpt uses ESC[A ESC[K to move up and clear? Sample: "\x1b[A\x1b[K[0/21968] No tests running."
    // We'll simulate similar
    let mut done = 0;
    for _ in 0..40 {
        if ctx.should_exit() { return false; }
        done += rng.gen_range(1..10);
        if done > total { done = total; }
        // generate list of test files
        let mut files = Vec::new();
        for _ in 0..rng.gen_range(5..12) {
            let cat = ["html","css","netinfo","mediacapture-extensions","secure-payment-confirmation","notifications","vibration","css/css-view-transitions","pointerevents","encoding"].choose(&mut rng).unwrap();
            files.push(format!("/{}/test-{}.html", cat, rng.gen_range(1..500)));
        }
        let line = format!("\x1b[A\x1b[K[{}/{}] {}", done, total, files.join(" "));
        if !ctx.print(&line, 150) { return false; }
        // occasionally unexpected result
        if rng.gen_bool(0.4) {
            let line2 = format!("\x1b[A\x1b[K    ▶ Unexpected subtest result in {}:", files[0]);
            if !ctx.print(&line2, 100) { return false; }
            let line3 = format!("    │ ERROR [expected PASS] FAIL test_{} assert_equals: expected {} but got {}", files[0], rng.gen_range(100..1000), rng.gen_range(100..1000));
            if !ctx.print(&line3, 100) { return false; }
        }
        if done >= total { break; }
    }
    true
}
