    let mut addr: u64 = rng.gen_range(0x400000000000..0x7fffffffffff) & !0xF;
    // align? Sample addresses like 7a16de999ff2f2d0, increment 0x10 each line
    // We'll start random and increment
    for _ in 0..60 {
        if ctx.should_exit() { return false; }
        let mut bytes = [0u8; 16];
        for b in bytes.iter_mut() { *b = rng.gen(); }
        let hex1: String = bytes[0..8].iter().map(|b| format!("{:02x}", b)).collect::<Vec<_>>().join(" ");
        // Actually format: "7a16de999ff2f2d0  e0 9b 67 7b 45 e5 6b 46  89 74 a6 53 d6 db dc 69  |..g{E.kF.t.S...i|"
        // Address (16 hex) + two spaces + 8 bytes + two spaces + 8 bytes + two spaces + |ascii|
        let h1: String = bytes[0..8].iter().map(|b| format!("{:02x}", b)).collect::<Vec<_>>().join(" ");
        let h2: String = bytes[8..16].iter().map(|b| format!("{:02x}", b)).collect::<Vec<_>>().join(" ");
        let ascii: String = bytes.iter().map(|&b| if b.is_ascii_graphic() || b == b' ' { b as char } else { '.' }).collect();
        let line = format!("{:016x}  {}  {}  |{}|", addr, h1, h2, ascii);
        if !ctx.print(&line, 80) { return false; }
        addr = addr.wrapping_add(0x10);
    }
    true
}

