use std::mem::zeroed;
pub struct Width(pub u16);
pub struct Height(pub u16);
pub fn terminal_size() -> Option<(Width, Height)> {
    unsafe {
        let mut ws: libc::winsize = zeroed();
        // Try stdout, stderr, stdin in order? Original terminal_size checks stdout? Let's check: it tries STDOUT, then STDERR, then STDIN? Actually it checks all? For simplicity, check STDOUT first.
        // If stdout is not tty, try stderr? But help output goes to stdout? When piped, stdout not tty, so return None.
        // When run in tmux with tty, stdout is tty, return size.
        // We'll check STDOUT, if fails try STDERR, then STDIN.
        for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
            if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == 0 {
                if ws.ws_col != 0 && ws.ws_row != 0 {
                    return Some((Width(ws.ws_col), Height(ws.ws_row)));
                }
            }
        }
        None
    }
}
